From 8412af447c38f7805122017efe18f9fe0ca54b69 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 20:40:26 +0100
Subject: [PATCH] shell/scripting: add writeTemporaryConfig for session-only
 changes

Every config change made from a script was saved to disk, so a widget or
wallpaper couldn't be changed just for the current session. The new
writeTemporaryConfig() applies the value right away without saving it.

BUG: 518887
---
 shell/scripting/applet.cpp | 55 +++++++++++++++++++++++++++++++-------
 shell/scripting/applet.h   |  3 +++
 2 files changed, 49 insertions(+), 9 deletions(-)

diff --git a/shell/scripting/applet.cpp b/shell/scripting/applet.cpp
index 9b69e32f93..a3e1df175b 100644
--- a/shell/scripting/applet.cpp
+++ b/shell/scripting/applet.cpp
@@ -10,6 +10,7 @@
 #include <QAction>
 #include <QQmlPropertyMap>

+#include <KConfigPropertyMap>
 #include <kconfigloader.h>
 #include <kservice.h>

@@ -99,8 +100,24 @@ QVariant Applet::readConfig(const QString &key, const QJSValue &def) const
 }

 void Applet::writeConfig(const QString &key, const QJSValue &value)
+{
+    writeConfig(key, value, KConfigBase::Normal);
+}
+
+void Applet::writeTemporaryConfig(const QString &key, const QJSValue &value)
+{
+    writeConfig(key, value, KConfigBase::WriteConfigFlags());
+}
+
+void Applet::writeConfig(const QString &key, const QJSValue &value, KConfigBase::WriteConfigFlags flags)
 {
     if (d->configGroup.isValid()) {
+        const bool persistent = flags & KConfigBase::Persistent;
+        if (!persistent) {
+            // write out pending changes first, or they would carry the temporary value to disk
+            d->configGroup.config()->sync();
+        }
+
         if (d->inWallpaperConfig) {
             // hacky, but only way to make the wallpaper react immediately
             auto *wallpaperGraphicsObject = applet()->property("wallpaperGraphicsObject").value<QObject *>();
@@ -112,18 +129,38 @@ void Applet::writeConfig(const QString &key, const QJSValue &value)
             // check if it can be written in the applets' configScheme
             if (KConfigSkeletonItem *item = configScheme->findItemByName(key)) {
                 item->setProperty(value.toVariant());
-                configScheme->blockSignals(true);
-                configScheme->save();
-                // why read? read will update KConfigSkeletonItem::mLoadedValue,
-                // allowing a write operation to be performed next time
-                configScheme->read();
-                configScheme->blockSignals(false);
-                Q_EMIT configScheme->configChanged();
+                if (persistent) {
+                    configScheme->blockSignals(true);
+                    configScheme->save();
+                    // why read? read will update KConfigSkeletonItem::mLoadedValue,
+                    // allowing a write operation to be performed next time
+                    configScheme->read();
+                    configScheme->blockSignals(false);
+                    Q_EMIT configScheme->configChanged();
+                } else {
+                    // configChanged() would reload the configuration from disk, so only update this value,
+                    // and mark it as loaded so that saving the configuration later doesn't write it out
+                    item->configGroup(configScheme->config()).writeEntry(item->key(), item->property(), flags);
+                    item->readConfig(configScheme->config());
+                    applet()->configuration()->insert(item->key(), item->property());
+                }
             }
         }

-        d->configGroup.writeEntry(key, value.toVariant());
-        d->configDirty = true;
+        d->configGroup.writeEntry(key, value.toVariant(), flags);
+        d->configDirty = d->configDirty || persistent;
+
+        if (!persistent && d->inWallpaperConfig) {
+            if (auto *wallpaperGraphicsObject = applet()->property("wallpaperGraphicsObject").value<QObject *>()) {
+                // mark the value as loaded, so saving the wallpaper settings later doesn't write it out
+                const auto loaders = wallpaperGraphicsObject->findChildren<KCoreConfigSkeleton *>(Qt::FindDirectChildrenOnly);
+                for (KCoreConfigSkeleton *loader : loaders) {
+                    if (KConfigSkeletonItem *item = loader->findItem(key)) {
+                        item->readConfig(loader->config());
+                    }
+                }
+            }
+        }
     }
 }

diff --git a/shell/scripting/applet.h b/shell/scripting/applet.h
index fa3030fb79..2e1763e01e 100644
--- a/shell/scripting/applet.h
+++ b/shell/scripting/applet.h
@@ -51,9 +51,12 @@ protected:
 public Q_SLOTS:
     virtual QVariant readConfig(const QString &key, const QJSValue &def = QString()) const;
     virtual void writeConfig(const QString &key, const QJSValue &value);
+    void writeTemporaryConfig(const QString &key, const QJSValue &value);
     virtual void reloadConfig();

 private:
+    void writeConfig(const QString &key, const QJSValue &value, KConfigBase::WriteConfigFlags flags);
+
     class Private;
     Private *const d;
 };
-- 
